export function burrowArtFor(category: string, ordinal = 1): BurrowArtAsset | undefined {
  return BURROW_ART[category]?.[Math.max(0, ordinal - 1)];
}

export function burrowArtForItem(item: MajorUpdateCatalogItem | undefined, fallbackCategory?: string): BurrowArtAsset | null | undefined {
  // Explicitly removed historical IDs stay blank even in stale pre-retirement
  // caches; never reinterpret their ordinal as another/current product.
  // null is an intentional empty visual; undefined still permits ordinary
  // unknown-item/category fallbacks at existing callers.
  if(item?.stable_id&&SHOP_REMOVED_ART_IDS?.has(item.stable_id))return null;
  // IDs, not names/ordinals, own all managed product art. Legacy cached rows
  // and non-Shop adventure collectibles retain their compatibility renderer.
  if(item?.stable_id&&SHOP_PRODUCT_ART[item.stable_id])return SHOP_PRODUCT_ART[item.stable_id];
  if(item?.metadata.catalogManaged)return undefined;
  if (item?.asset?.renderer === 'r2' && typeof item.asset.url === 'string' && item.tags.includes('adventure_v2_gift')) {
    return { source: { uri: item.asset.url }, width: 600, height: 600,
      bounds: Array.isArray(item.asset.bounds) && item.asset.bounds.length === 4 ? item.asset.bounds as [number,number,number,number] : [0,0,600,600] };
  }
  // The slot is authoritative for room rendering. Old cached catalog rows may
  // still carry the pre-migration category (storage/plants/etc.).
  const category = fallbackCategory ?? item?.category;
  if (!category || !BURROW_ART[category]) return undefined;
  if (category === 'windows' && item?.metadata.windowFrameKey) {
    return BURROW_ART.windows.find(art => art.windowFrameKey === item.metadata.windowFrameKey) ?? BURROW_ART.windows[0];
  }
  // Default has no clothing icon. Never map a stale outfit to another product.
  if (category === 'outfits') {
    const ordinal = item?.metadata.artOrdinal;
    return item?.asset?.renderer === 'layered_bunny' && !item.metadata.starter
      && typeof ordinal === 'number' && Number.isInteger(ordinal) && ordinal > 0
      ? burrowArtFor(category, ordinal) : undefined;
  }
  // Starter art follows the supplied Default-* file, regardless of old metadata.
  const ordinal = item?.metadata.starter ? 1 : item?.metadata.artOrdinal ?? 1;
  return burrowArtFor(category, ordinal) ?? burrowArtFor(category);
}
